import{c as t,Q as a,j as l,m as r}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"Fees & Settlement Details - Hyperliquid Recovery Bot","description":"Clear breakdown of service fees (0.5%) and withdrawal fees (2 USDC) for recovery. Understand the calculation: You Will Receive = Recoverable Value - Total Cost.","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/en/fee-and-settlement"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/fee-and-settlement"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/fee-and-settlement"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/fee-and-settlement"}],["meta",{"name":"keywords","content":"Hyperliquid recovery fee, withdrawal gas cost, service fee Web3 recovery, payout settlement time"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"Fees & Settlement Details - Hyperliquid Recovery Bot"}],["meta",{"property":"og:description","content":"Clear breakdown of service fees (0.5%) and withdrawal fees (2 USDC) for recovery. Understand the calculation: You Will Receive = Recoverable Value - Total Cost."}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/en/fee-and-settlement"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"Fees & Settlement Details - Hyperliquid Recovery Bot"}],["meta",{"name":"twitter:description","content":"Clear breakdown of service fees (0.5%) and withdrawal fees (2 USDC) for recovery. Understand the calculation: You Will Receive = Recoverable Value - Total Cost."}]]},"headers":[],"relativePath":"en/fee-and-settlement.md","filePath":"en/fee-and-settlement.md","lastUpdated":null}'),i={name:"en/fee-and-settlement.md"};function o(n,e,s,d,c,h){return a(),l("div",null,[...e[0]||(e[0]=[r(`<h1 id="fee-and-settlement" tabindex="-1">Fee and Settlement <a class="header-anchor" href="#fee-and-settlement" aria-label="Permalink to &quot;Fee and Settlement&quot;">​</a></h1><p>This page explains what fees you may pay, how they are calculated, and what you can expect to receive.</p><h2 id="fee-terms" tabindex="-1">Fee Terms <a class="header-anchor" href="#fee-terms" aria-label="Permalink to &quot;Fee Terms&quot;">​</a></h2><ul><li><code>Service Fee</code>: 0.5% of recovered value, minimum 1 USDC.</li><li><code>Withdrawal Fees</code>: Hyperliquid charges 1 USDC per withdrawal.</li><li><code>Total Cost</code>: Service Fee + Withdrawal Fees.</li><li><code>You Will Receive</code>: Estimated Recoverable Value - Total Cost.</li></ul><p><code>Estimated Recoverable Value</code> means the assets that can actually be handled in this run. Assets that are still locked or waiting are not counted yet.</p><h2 id="fee-structure" tabindex="-1">Fee Structure <a class="header-anchor" href="#fee-structure" aria-label="Permalink to &quot;Fee Structure&quot;">​</a></h2><p>Recovery usually includes two withdrawals, so <code>Withdrawal Fees = 2 USDC</code>:</p><ol><li>Service fee withdrawal: 1 USDC platform fee</li><li>Final withdrawal: 1 USDC platform fee</li></ol><h2 id="formulas" tabindex="-1">Formulas <a class="header-anchor" href="#formulas" aria-label="Permalink to &quot;Formulas&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service Fee = max(Estimated Recoverable Value x 0.5%, 1 USDC)</span></span>
<span class="line"><span>Withdrawal Fees = 2 USDC</span></span>
<span class="line"><span>Total Cost = Service Fee + Withdrawal Fees</span></span>
<span class="line"><span>You Will Receive = Estimated Recoverable Value - Total Cost</span></span></code></pre></div><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Estimated Recoverable Value</th><th>Service Fee</th><th>Withdrawal Fees</th><th>Total Cost</th><th>You Will Receive</th></tr></thead><tbody><tr><td>100 USDC</td><td>1.00</td><td>2.00</td><td>3.00</td><td>97.00</td></tr><tr><td>1,000 USDC</td><td>5.00</td><td>2.00</td><td>7.00</td><td>993.00</td></tr><tr><td>10,000 USDC</td><td>50.00</td><td>2.00</td><td>52.00</td><td>9,948.00</td></tr></tbody></table><h2 id="what-you-see-on-the-result-page" tabindex="-1">What You See on the Result Page <a class="header-anchor" href="#what-you-see-on-the-result-page" aria-label="Permalink to &quot;What You See on the Result Page&quot;">​</a></h2><ul><li>Before execution: estimated values.</li><li>After execution: actual values.</li><li>Small differences may happen because prices can change during execution.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Address detection is always free.</li><li>If nothing is successfully handled, no unnecessary service fee is charged.</li><li>Final withdrawal must still meet Hyperliquid&#39;s minimum withdrawal requirement (commonly 1.01 USDC).</li><li>After withdrawal is submitted, arrival on Arbitrum depends on Hyperliquid processing speed and may take several to more than ten minutes.</li></ul>`,16)])])}const p=t(i,[["render",o]]);export{m as __pageData,p as default};
